head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageId = "ULDTMS04090";
scwin.storageId = "";
scwin.storageSubId = "";

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 화면 전환 파라미터(storageId·대분류 정보)를 수신해 상단 조회 조건에 표시하고 배정된 중분류 목록을 조회한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        scwin.storageId = $c.data.getParameter("storageId");

        tbx_upEditClssCd.setValue($c.data.getParameter("editClssCd"));
        tbx_upEditClssNm.setValue($c.data.getParameter("editClssNm"));
        tbx_upEditClssEngNm.setValue($c.data.getParameter("editClssEngNm"));
        tbx_ldMktTpNm.setValue($c.data.getParameter("ldMktTpNm"));
        tbx_editUseTpNm.setValue($c.data.getParameter("editUseTpNm"));

        scwin.fnSearch();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDTMS04090.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name btn_list_onclick
 * @description [목록] 버튼 클릭 — 편집기대분류 목록 화면(ULDTMS04070)으로 이동한다(storageId 보유 시 함께 전달).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_list_onclick(e);
 */
scwin.btn_list_onclick = function (e) {
    const params = {};
    if (scwin.storageId !== "") {
        params.storageId = scwin.storageId;
    }
    const url_ = "/ui/TMS/ULDTMS04070.xml";
    $c.win.moveUrl(url_, params);
};

/**
 * @method
 * @name btn_delete_onclick
 * @description [선택 삭제] 버튼 클릭 — 체크된 삭제 대상(편집기중분류코드)을 수집해 확인 후 삭제 처리를 요청한다. 체크 항목이 없으면 안내한다.
 * @param {Object} rowIndex 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_delete_onclick(e);
 */
scwin.btn_delete_onclick = async function (rowIndex) {
    // 체크된 삭제 대상 수집
    const editClssCdList = [];
    for (let i=0; i < dlt_list.getRowCount(); i++) {
        if (dlt_list.getCellData(i, "CHK") === "1") {
            editClssCdList.push(dlt_list.getCellData(i, "editClssCd"));
        }
    }

    // 삭제 처리
    if (editClssCdList.length > 0) {
        if (await $c.win.confirm("삭제 하시겠습니까?")) {
            const params = {};
            params.editClssCdList = editClssCdList;

            $c.sbm.execute(sbm_del, params);
        }
    } else {
        $c.win.alert("삭제 할 배정된 편집기 중분류를 체크해 주세요.");
    }
};

/**
 * @method
 * @name btn_insert_onclick
 * @description [중분류 추가] 버튼 클릭 — 편집기중분류 등록 팝업을 열고, 저장(refreshYn === "Y") 시 목록을 재조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_insert_onclick(e);
 */
scwin.btn_insert_onclick = async function (e) {
    const params = {};
    params.upEditClssCd = tbx_upEditClssCd.getValue();
    params.ldMktTpCd = $c.data.getParameter("ldMktTpCd");

    const result = await scwin.fnPopUp("편집기중분류 등록", params);
    if (!$c.util.isEmpty(result) && result.refreshYn === "Y") {
        scwin.fnSearch();
    }
};

/**
 * @method
 * @name grd_list_oncellclick
 * @description 목록 셀 클릭 — 서식명(편집기중분류명) 컬럼 클릭 시 그리드 위치 정보를 저장하고 편집기중분류 변경 팝업을 연다. 저장(refreshYn === "Y") 시 목록을 재조회하고, 취소 시 저장한 위치 정보를 삭제한다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 컬럼 인덱스
 * @param {String} columnId 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grd_list_oncellclick(0, 2, "editClssNm");
 */
scwin.grd_list_oncellclick = async function (rowIndex, columnIndex, columnId) {
    // 서식명일 경우 상세 조회
    if (columnId === "editClssNm") {
        const params = {};
        params.editClssCd = dlt_list.getCellData(rowIndex, "editClssCd");
        params.upEditClssCd = tbx_upEditClssCd.getValue();
        params.ldMktTpCd = dlt_list.getCellData(rowIndex, "ldMktTpCd");
        params.editUseTpCd = dlt_list.getCellData(rowIndex, "editUseTpCd");
        params.editClssNm = dlt_list.getCellData(rowIndex, "editClssNm");
        params.editClssEngNm = dlt_list.getCellData(rowIndex, "editClssEngNm");
        params.storageSubId = scwin.pageId;

        // 위치 정보 저장
        $c.tms.setKeywordSave(scwin.pageId, grd_list);

        const result = await scwin.fnPopUp("편집기중분류 변경", params);
        if (!$c.util.isEmpty(result) && result.refreshYn === "Y") {
            //  그리드 위치 처리
            if (!$c.util.isEmpty(result.storageSubId)) {
                scwin.storageSubId = result.storageSubId;
            }
            scwin.fnSearch();
        } else {
            $c.tms.delKeyword(scwin.pageId);
        }
    }
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name sbm_list_submitdone
 * @description sbm_list 콜백 — 조회 성공 시 저장된 그리드 스크롤 위치가 있으면 복원하고, 실패 시 메시지를 알린다.
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example (sbm_list ev:submitdone 바인딩으로 자동 호출)
 */
scwin.sbm_list_submitdone = function (e) {
    // 조회 성공인 경우
    const result = e.responseJSON;
    if (result.success) {
        if (!$c.util.isEmpty(scwin.storageSubId)) {
            const scrollTop = $c.tms.getKeywordSave(scwin.storageSubId);
            // 재조회 여부 체크
            if (!$c.util.isEmpty(scrollTop)) {
                grd_list.setScrollTop(scrollTop);
            }
            scwin.storageSubId = "";
        }
    } else {
        $c.win.alert(result.message);
    }
};

/**
 * @method
 * @name sbm_del_submitdone
 * @description sbm_del 콜백 — 삭제 성공 시 완료 메시지 후 목록을 재조회하고, 실패 시 메시지를 알린다.
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example (sbm_del ev:submitdone 바인딩으로 자동 호출)
 */
scwin.sbm_del_submitdone = async function (e) {
    const result = e.responseJSON;
    if (result.success) {
        await $c.win.alert("삭제 되었습니다.");
        scwin.fnSearch();
    } else {
        $c.win.alert(result.message);
    }
};

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name fnSearch
 * @description 코드 정보 조회 — 대분류코드(tbx_upEditClssCd) 기준으로 배정된 편집기중분류 목록을 조회한다.
 * @returns {void}
 * @hidden N
 * @example scwin.fnSearch();
 */
scwin.fnSearch = function () {
    // 코드 정보 조회
    $c.sbm.setAction(sbm_list, "/api/code/edit-midclss/" + tbx_upEditClssCd.getValue());
    $c.sbm.execute(sbm_list);
};

/**
 * @method
 * @name fnPopUp
 * @description 편집기중분류 등록/변경 팝업(ULDTMS04120)을 연다.
 * @param {String} title 팝업 제목
 * @param {Object} params 팝업 전달 파라미터
 * @returns {Promise} 팝업 종료 결과(닫힘 파라미터)
 * @hidden N
 * @example const result = await scwin.fnPopUp("편집기중분류 등록", params);
 */
scwin.fnPopUp = function (title, params) {
    const url_ = "/ui/TMS/ULDTMS04120.xml";
    const options = {
        id: "ULDTMS04120_POP",
        popupName: title,
        width: "680",
        height: "340",
        frameModal: "top"
    };
    return $c.win.openPopup(url_, options, params);
};
